<?php include "../auth/cek_login.php";include "../koneksi.php";$id=$_GET['id'];$t=mysqli_fetch_assoc(mysqli_query($conn,"SELECT t.*,p.nama,p.no_hp,p.alamat FROM transaksi t JOIN pelanggan p ON t.id_pelanggan=p.id WHERE t.id=$id"));$q=mysqli_query($conn,"SELECT d.*,b.nama_barang FROM detail_transaksi d JOIN barang b ON d.id_barang=b.id WHERE d.id_transaksi=$id");?><!doctype html><html><head><title>Detail Transaksi</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Detail Transaksi <?=$t['kode_transaksi']?></h1><p>Pelanggan: <?=$t['nama']?> | <?=$t['no_hp']?></p><table><tr><th>Barang</th><th>Jumlah</th><th>Harga</th><th>Subtotal</th></tr><?php while($d=mysqli_fetch_assoc($q)):?><tr><td><?=$d['nama_barang']?></td><td><?=$d['jumlah']?></td><td>Rp <?=number_format($d['harga_sewa'])?></td><td>Rp <?=number_format($d['subtotal'])?></td></tr><?php endwhile;?></table><h3>Total: Rp <?=number_format($t['total_harga'],0,',','.')?></h3><a class="btn" href="index.php">Kembali</a></div></body></html>